-- Greenhouse Events: import the acts currently on the talent page.
-- Run once, after schema.sql. Safe to run again (existing artists are skipped).


  select a.id, a.cover_url, 0 from public.artists a
  where a.cover_url is not null and not exists (select 1 from public.artist_photos p where p.artist_id = a.id);

-- Full names are kept privately; the website shows first names only.
